INSERT INTO `app_vecsa_marketing_events` VALUES (1,'77e2f9df-45f3-49d3-8066-20dbaef0d828','2024-09-03','2024-09-03','Imagen principal',NULL,'principal','public',NULL,'Imagen principal','https://res.cloudinary.com/dtq6y1rf9/image/upload/v1725401054/vecsa_eventos/77e2f9df-45f3-49d3-8066-20dbaef0d828/1725401054_77e2f9df-45f3-49d3-8066-20dbaef0d828.jpg','2024-09-04 04:04:13','2024-09-04 04:04:14',NULL),(2,'c46fe6a7-4b9d-46ce-bb86-029cff787980','2024-09-03','2024-09-03','Imagen principal dos',NULL,'principal','public',NULL,'Imagen pricipal dos','https://res.cloudinary.com/dtq6y1rf9/image/upload/v1725401268/vecsa_eventos/c46fe6a7-4b9d-46ce-bb86-029cff787980/1725401268_c46fe6a7-4b9d-46ce-bb86-029cff787980.jpg','2024-09-04 04:07:48','2024-09-04 04:07:49',NULL),(3,'530b6533-3ed7-4806-90fd-e279ae36da95','2024-07-12','2024-07-12','Rodada Monumental Tecozautla, Hidalgo.',NULL,'schedule','public',NULL,'¡Tenemos una salida programada!\r\n\r\nÚnete a nosotros el 14 de julio para una emocionante aventura de fin de semana con una rodada monumental hacia Tecozautla, Hidalgo.\r\n\r\n¿Te animas?\r\n\r\nRegístrate y confirma tu asistencia a través de WhatsApp al 771 795 4749\r\n\r\n#BMWMotorradVecsaHidalgo #TuPuntoDeEncuentro','https://res.cloudinary.com/dtq6y1rf9/image/upload/v1725401521/vecsa_eventos/530b6533-3ed7-4806-90fd-e279ae36da95/1725401520_530b6533-3ed7-4806-90fd-e279ae36da95.jpg','2024-09-04 04:12:00','2024-09-04 04:12:02',NULL),(4,'fedc3051-c143-4f47-afc4-de821eb57490','2024-07-12','2024-07-12','RODADA MINI',NULL,'schedule','public',NULL,'Acompáñanos a nuestra próxima rodada y vive una experiencia ·#MINI\r\n\r\nDía: viernes 12 de julio de 2024\r\n\r\nHora: 6pm\r\n\r\nPunto de reunión: ·#MINIVecsaHidalgo\r\n\r\n📍Distribuidor Vial La Paz #113 Colonia Adolfo López Mateos, Pachuca Hgo. CP 42094… See more','https://res.cloudinary.com/dtq6y1rf9/image/upload/v1725401672/vecsa_eventos/fedc3051-c143-4f47-afc4-de821eb57490/1725401672_fedc3051-c143-4f47-afc4-de821eb57490.jpg','2024-09-04 04:14:32','2024-09-04 04:14:33',NULL),(5,'0616ecf9-c899-4aa5-8544-f1e6ac05f0a4','2024-07-19','2024-07-19','BMW E-Drive Night',NULL,'schedule','public',NULL,'Nos complace invitarle a la exclusiva BMW E-Drive Night VECSA Hidalgo! Acompáñenos el viernes 19 de julio a las 6:00 p.m. para disfrutar de una velada dedicada a la innovación y el futuro de la movilidad eléctrica.\r\n\r\nDescubra nuestra gama de vehículos totalmente eléctricos e híbridos, experimente la emoción de conducir un BMW electrificado y conozca las últimas tecnologías que están revolucionando la industria automotriz.\r\n\r\nEn esta noche especial, podrá explorar nuestros últimos modelos eléctricos e híbridos, realizar pruebas de manejo, disfrutar de presentaciones sobre movilidad eléctrica, compartir con otros entusiastas de BMW y deleitarse con música en vivo, aperitivos y bebidas.\r\n\r\nPara reservar su asistencia, por favor comuníquese al teléfono 771 795 47 49 o envíe un correo electrónico a\r\n\r\ncrmhidalgo@bmwvecsa.com.\r\n\r\n¡Esperamos contar con su presencia en esta noche electrizante!','https://res.cloudinary.com/dtq6y1rf9/image/upload/v1725401904/vecsa_eventos/0616ecf9-c899-4aa5-8544-f1e6ac05f0a4/1725401904_0616ecf9-c899-4aa5-8544-f1e6ac05f0a4.jpg','2024-09-04 04:18:24','2024-09-04 04:18:25',NULL),(6,'3556ac0f-63ac-4aa6-a1b0-5edfc7b59563','2024-08-17','2024-08-17','3ER RALLY SIERRA HIDALGUENSE',NULL,'schedule','public',NULL,NULL,'https://res.cloudinary.com/dtq6y1rf9/image/upload/v1725403951/vecsa_eventos/3556ac0f-63ac-4aa6-a1b0-5edfc7b59563/1725403951_3556ac0f-63ac-4aa6-a1b0-5edfc7b59563.jpg','2024-09-04 04:52:31','2024-09-04 04:52:34',NULL),(7,'157fc6e8-1a7b-4131-a2d4-8f2ecaf5a425','2024-08-19','2024-08-19','RUTA DE La luna llena',NULL,'schedule','public',NULL,NULL,'https://res.cloudinary.com/dtq6y1rf9/image/upload/v1725404097/vecsa_eventos/157fc6e8-1a7b-4131-a2d4-8f2ecaf5a425/1725404097_157fc6e8-1a7b-4131-a2d4-8f2ecaf5a425.jpg','2024-09-04 04:54:57','2024-09-04 04:54:58',NULL),(8,'91c4a692-ebee-40e0-af89-1c10b2b47f60','2024-08-25','2024-08-25','VIVE LA PASIÓN BMW MOTORRAD CLÍNICA DE MANEJO',NULL,'schedule','public',NULL,NULL,'https://res.cloudinary.com/dtq6y1rf9/image/upload/v1725404227/vecsa_eventos/91c4a692-ebee-40e0-af89-1c10b2b47f60/1725404227_91c4a692-ebee-40e0-af89-1c10b2b47f60.jpg','2024-09-04 04:57:07','2024-09-04 04:57:09',NULL),(9,'e51ddeab-5e59-4dc6-926e-2edf06dca7d7','2024-08-25','2024-08-25','VIVE LA PASIÓN BMW MOTORRAD CLÍNICA DE MANEJO',NULL,'community','public',NULL,'¡Gracias por vivir la pasión BMW Motorrad con nosotros el pasado 25 de agosto! 🏍️\r\n\r\nQueremos agradecer a todos los pilotos que participaron en nuestra Clínica de Manejo. Su entusiasmo y ganas de mejorar hicieron de este evento una experiencia llena de aprendizaje y adrenalina.\r\n\r\nNos encanta ver a nuestra comunidad crecer y volverse más segura y ágil en cada ruta. ¡Nos vemos en la próxima para seguir dominando juntos cada kilómetro!','https://res.cloudinary.com/dtq6y1rf9/image/upload/v1725404623/vecsa_eventos/e51ddeab-5e59-4dc6-926e-2edf06dca7d7/1725404623_e51ddeab-5e59-4dc6-926e-2edf06dca7d7.jpg','2024-09-04 05:03:43','2024-09-04 05:03:44',NULL),(10,'a5359581-aa4b-4300-9d42-7fd6924b7f8b','2024-08-19','2024-08-19','RUTA DE LA LUNA LLENA',NULL,'community','public',NULL,NULL,'https://res.cloudinary.com/dtq6y1rf9/image/upload/v1725405027/vecsa_eventos/a5359581-aa4b-4300-9d42-7fd6924b7f8b/1725405027_a5359581-aa4b-4300-9d42-7fd6924b7f8b.jpg','2024-09-04 05:10:27','2024-09-04 05:10:29',NULL),(11,'49bae500-8ed2-499c-9bce-4a68380d1ba7','2024-08-17','2024-08-17','RALLY SIERRE HIDALGUENSE',NULL,'community','public',NULL,'¡Gracias por acompañarnos en el 3er Rally Sierra Hidalguense! 🏍️\r\n\r\nQueremos agradecer a todos los apasionados del motociclismo que se unieron a este emocionante evento. Su energía, espíritu de aventura y amor por la carretera hicieron de este rally una experiencia inolvidable.\r\n\r\n¡Nos vemos en la siguiente ruta para seguir compartiendo la pasión por BMW Motorrad y la aventura sobre dos ruedas!','https://res.cloudinary.com/dtq6y1rf9/image/upload/v1725405299/vecsa_eventos/49bae500-8ed2-499c-9bce-4a68380d1ba7/1725405299_49bae500-8ed2-499c-9bce-4a68380d1ba7.jpg','2024-09-04 05:14:59','2024-09-04 05:15:01',NULL),(12,'1bb50653-742b-44a2-a45a-421789b0dbc2','2024-07-14','2024-07-14','Rodada Tecozautla, Hidalgo.',NULL,'community','public',NULL,'¡Agradecemos enormemente por rodar junto a nosotros!\r\n\r\nQueremos expresar nuestro profundo agradecimiento a todos los amantes de la aventura y la libertad sobre dos ruedas que nos acompañaron en la emocionante travesía de BMW MOTORRAD VECSA Hidalgo a Tecozautla, Hidalgo el pasado 14 de julio.\r\n\r\nEl entusiasmo y la energía que aportaron hicieron de este viaje una experiencia verdaderamente memorable. Nos sentimos privilegiados por haber compartido kilómetros de carretera y paisajes impresionantes con cada uno de ustedes.\r\n\r\nEsperamos seguir disfrutando juntos de emocionantes aventuras sobre dos ruedas en el futuro.\r\n\r\n¡Nos vemos en la próxima aventura!\r\n\r\nMake Life A Ride.','https://res.cloudinary.com/dtq6y1rf9/image/upload/v1725405663/vecsa_eventos/1bb50653-742b-44a2-a45a-421789b0dbc2/1725405663_1bb50653-742b-44a2-a45a-421789b0dbc2.jpg','2024-09-04 05:21:03','2024-09-04 05:21:04',NULL),(13,'86551d0f-c6a3-48e4-bd09-0d38c6d88021','2024-07-12','2024-07-12','RODADA MINI',NULL,'community','public',NULL,'¡Agradecemos enormemente por rodar junto a nosotros MINIacs!\r\n\r\nQueremos expresar nuestro profundo agradecimiento a todos los amantes de la aventura y la libertad sobre cuatro ruedas que nos acompañaron en la emocionante travesía de MINI VECSA Hidalgo , el pasado 12 de julio.\r\n\r\nEl entusiasmo y la energía que aportaron, junto con el inigualable estilo MINI, hicieron de este viaje una experiencia verdaderamente memorable. Nos sentimos privilegiados por haber compartido kilómetros de carretera y paisajes impresionantes con cada uno de ustedes.','https://res.cloudinary.com/dtq6y1rf9/image/upload/v1725406447/vecsa_eventos/86551d0f-c6a3-48e4-bd09-0d38c6d88021/1725406446_86551d0f-c6a3-48e4-bd09-0d38c6d88021.jpg','2024-09-04 05:34:06','2024-09-04 05:34:08',NULL),(14,'ba625dd5-7eb3-47d7-9e8b-d10152101a58','2024-06-14','2024-06-14','Noche de Casino VECSA Hidalgo',NULL,'community','public',NULL,'¡Agradecemos a todos los que asistieron a nuestra exclusiva Noche de Casino VECSA Hidalgo!\r\n\r\nFue una noche llena de emoción, juegos y la inigualable elegancia de BMW. Su presencia hizo que la velada fuera realmente especial','https://res.cloudinary.com/dtq6y1rf9/image/upload/v1725407460/vecsa_eventos/ba625dd5-7eb3-47d7-9e8b-d10152101a58/1725407460_ba625dd5-7eb3-47d7-9e8b-d10152101a58.jpg','2024-09-04 05:51:00','2024-09-04 05:51:01',NULL);
/*!40000 ALTER TABLE `app_vecsa_marketing_events` ENABLE KEYS */;
