--
-- Table structure for table `app_vecsa_reward_points`
--

DROP TABLE IF EXISTS `app_vecsa_reward_points`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `app_vecsa_reward_points` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `redeemed` tinyint(1) NOT NULL DEFAULT '0',
  `earned_points` double DEFAULT NULL,
  `purchase_amount` double DEFAULT NULL,
  `initial_mileage` int unsigned DEFAULT NULL,
  `final_mileage` int unsigned DEFAULT NULL,
  `detail` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sale_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `image_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customer_reward_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
