INSERT INTO `app_vecsa_vehicle_updates` VALUES (1,'Vehicle Controller: Update vehicle','[{\"vin\":\"2C3CDYBTXDH635725\",\"page_status\":\"valuing\",\"mileage\":231421,\"type\":\"car\",\"cylinders\":\"8\",\"exterior_color\":\"negro\",\"transmission\":\"semiautomatic\",\"uuid\":\"89b67b15-a5be-4883-99bb-08976ad38d64\",\"created_at\":\"2025-01-23 18:48:14\"},{\"engine_type\":\"3.5\",\"plates\":\"OGN2131\",\"country_of_origin\":\"ALEMANIA\",\"auto_start_stop\":\"YES\",\"intake_engine\":\"TURBO\",\"vehicle_id\":1,\"created_at\":\"2025-01-23 18:48:14\"}]','{\"vin\": \"2C3CDYBTXDH635725\", \"body\": \"sedan\", \"line\": \"recta\", \"type\": \"car\", \"year\": \"2020\", \"brand\": \"bmw\", \"model\": \"x3\", \"plates\": \"OGN2131\", \"mileage\": 231421, \"version\": \"REC\", \"location\": \"vecsa hidalgo\", \"cylinders\": \"8\", \"engine_type\": \"3.5\", \"page_status\": \"valuing\", \"transmission\": \"semiautomatic\", \"intake_engine\": \"turbo\", \"exterior_color\": \"Negro\", \"valuation_uuid\": \"eaeb33b1-c515-4960-b203-a22710f26cb8\", \"auto_start_stop\": \"yes\", \"dealership_name\": \"vecsa hidalgo\", \"technician_uuid\": \"636e8075-58c7-422c-b7fa-14ab6ac36422\", \"country_of_origin\": \"alemania\"}',102,1,'2025-01-24 00:48:14','2025-01-24 00:48:14',NULL),(2,'Vehicle Controller: Update vehicle','[{\"vin\":\"WBA65GP09SN323721\",\"name\":\"BMW X3 30e xDrive (H\\u00edbrido\\/Autom\\u00e1tico)\",\"description\":\"BMW X3 30e xDrive 2025 representa la evoluci\\u00f3n de la conducci\\u00f3n h\\u00edbrida enchufable en el segmento de los SUV de lujo. Este veh\\u00edculo combina un motor de gasolina de 4 cilindros con un sistema el\\u00e9ctrico, entregando una potencia total de 299 hp y un par de 332 lb-pie, lo que se traduce en una aceleraci\\u00f3n de 0 a 100 km\\/h en 6.2 segundos. Su sistema xDrive garantiza tracci\\u00f3n total, mientras que su interior, equipado con tecnolog\\u00eda de vanguardia como una pantalla t\\u00e1ctil de 14.9 pulgadas y un cuadro de instrument