--
-- Table structure for table `app_vecsa_vehicle_valuations`
--

DROP TABLE IF EXISTS `app_vecsa_vehicle_valuations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `app_vecsa_vehicle_valuations` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `book_trade_in_offer` double DEFAULT NULL,
  `book_sale_price` double DEFAULT NULL,
  `intellimotors_trade_in_offer` double DEFAULT NULL,
  `intellimotors_sale_price` double DEFAULT NULL,
  `labor_cost` double DEFAULT NULL,
  `spare_parts_cost` double DEFAULT NULL,
  `body_work_painting_cost` double DEFAULT NULL,
  `estimated_total` double DEFAULT NULL,
  `trade_in_final` double DEFAULT NULL,
  `final_offer` double DEFAULT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'to_appraise',
  `status_repairs` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending_entry',
  `status_parts` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending_entry',
  `status_acquisition` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'to_acquire',
  `acquisition_pdf` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `comments` text COLLATE utf8mb4_unicode_ci,
  `take_type` text COLLATE utf8mb4_unicode_ci,
  `vehicle_id` bigint unsigned DEFAULT NULL,
  `dealership_id` bigint unsigned DEFAULT NULL,
  `appointment_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `app_vecsa_vehicle_valuations_uuid_unique` (`uuid`),
  KEY `app_vecsa_vehicle_valuations_vehicle_id_foreign` (`vehicle_id`),
  KEY `app_vecsa_vehicle_valuations_dealership_id_foreign` (`dealership_id`),
  KEY `app_vecsa_vehicle_valuations_appointment_id_foreign` (`appointment_id`),
  CONSTRAINT `app_vecsa_vehicle_valuations_appointment_id_foreign` FOREIGN KEY (`appointment_id`) REFERENCES `app_vecsa_customer_appointments` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `app_vecsa_vehicle_valuations_dealership_id_foreign` FOREIGN KEY (`dealership_id`) REFERENCES `app_vecsa_dealerships` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `app_vecsa_vehicle_valuations_vehicle_id_foreign` FOREIGN KEY (`vehicle_id`) REFERENCES `app_vecsa_vehicles` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

