DROP TABLE IF EXISTS `app_vecsa_vehicles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `app_vecsa_vehicles` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(90) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `vin` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `purchase_date` date DEFAULT NULL,
  `sale_price` double DEFAULT NULL,
  `list_price` double DEFAULT NULL,
  `offer_price` double DEFAULT NULL,
  `mileage` int unsigned DEFAULT NULL,
  `type` enum('car','moto','truck','other') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category` enum('new','pre_owned','demo') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cylinders` int unsigned DEFAULT NULL,
  `interior_color` varchar(90) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `exterior_color` varchar(90) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `transmission` enum('manual','automatic','semiautomatic','cvt','triptronic','dual-clutch') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fuel_type` enum('gasoline','diesel','electric','hybrid','hydrogen','natural_gas') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `drive_train` varchar(90) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `page_status` enum('active','inactive','sale','valuing') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'inactive',
  `spec_sheet` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `brand_id` bigint unsigned DEFAULT NULL,
  `line_id` bigint unsigned DEFAULT NULL,
  `model_id` bigint unsigned DEFAULT NULL,
  `version_id` bigint unsigned DEFAULT NULL,
  `body_id` bigint unsigned DEFAULT NULL,
  `dealership_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `app_vecsa_vehicles_uuid_unique` (`uuid`),
  KEY `app_vecsa_vehicles_brand_id_foreign` (`brand_id`),
  KEY `app_vecsa_vehicles_line_id_foreign` (`line_id`),
  KEY `app_vecsa_vehicles_model_id_foreign` (`model_id`),
  KEY `app_vecsa_vehicles_version_id_foreign` (`version_id`),
  KEY `app_vecsa_vehicles_body_id_foreign` (`body_id`),
  KEY `app_vecsa_vehicles_dealership_id_foreign` (`dealership_id`),
  CONSTRAINT `app_vecsa_vehicles_body_id_foreign` FOREIGN KEY (`body_id`) REFERENCES `app_vecsa_vehicle_bodies` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `app_vecsa_vehicles_brand_id_foreign` FOREIGN KEY (`brand_id`) REFERENCES `app_vecsa_vehicle_brands` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `app_vecsa_vehicles_dealership_id_foreign` FOREIGN KEY (`dealership_id`) REFERENCES `app_vecsa_dealerships` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `app_vecsa_vehicles_line_id_foreign` FOREIGN KEY (`line_id`) REFERENCES `app_vecsa_brand_lines` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `app_vecsa_vehicles_model_id_foreign` FOREIGN KEY (`model_id`) REFERENCES `app_vecsa_line_models` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `app_vecsa_vehicles_version_id_foreign` FOREIGN KEY (`version_id`) REFERENCES `app_vecsa_model_versions` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
