INSERT INTO `app_vecsa_vehicles` VALUES (1,'89b67b15-a5be-4883-99bb-08976ad38d64',NULL,NULL,'2C3CDYBTXDH635725',NULL,NULL,NULL,NULL,231421,'car',NULL,8,NULL,'negro','semiautomatic',NULL,NULL,'valuing',NULL,2,6,57,57,2,6,'2025-01-24 00:48:14','2025-01-24 00:48:14',NULL),(2,'f11d1eb2-3a01-454e-8012-a9d3289a50f2','BMW X3 30e xDrive (Híbrido/Automático)','BMW X3 30e xDrive 2025 representa la evolución de la conducción híbrida enchufable en el segmento de los SUV de lujo. Este vehículo combina un motor de gasolina de 4 cilindros con un sistema eléctrico, entregando una potencia total de 299 hp y un par de 332 lb-pie, lo que se traduce en una aceleración de 0 a 100 km/h en 6.2 segundos. Su sistema xDrive garantiza tracción total, mientras que su interior, equipado con tecnología de vanguardia como una pantalla táctil de 14.9 pulgadas y un cuadro de instrumentos digital de 12.3 pulgadas, ofrece una experiencia de conducción premium. Además, su autonomía eléctrica permite una conducción más sostenible, haciendo de este BMW X3 una opción versátil y eficiente.\nAccesorios Adicionales: 3MB Línea ext. aluminio satin, 552 Faros LED autoadaptables, 688 Harman Kardon surround so, 6NX Espacio wireless charging','WBA65GP09SN323721','2025-03-17',1570800,1494900,NULL,0,'car','new',4,'veganza | espresso brown','alpine white','automatic','hybrid',NULL,'active',NULL,2,7,58,58,3,7,'2025-03-17 23:59:50','2025-04-07 19:13:12',NULL),(3,'5d0eea0e-fc71-462a-a720-cce4b16ab9ac','BMW X3 M40i','¡Adquiere un seminuevo ya mismo!\nUn año de garantía\nUnidades verificadas por revisión de 100 puntos de calidad\nDocumentación 100% verificada\nCrédito desde el 20% de enganche y plazo de hasta 48 meses\nTenemos opciones si no compruebas ingresos\nFactura de agencia','WBA85DP06RN250731','2025-05-06',1120000,1120000,NULL,17480,'car','pre_owned',6,'marron','brooklyn grey','automatic','gasoline',NULL,'active',NULL,2,7,59,59,3,1,'2025-05-19 15:51:31','2025-05-19 15:53:53',NULL),(4,'e2a82ee7-7272-45fa-b9a2-6863